import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Instant;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderPlacedOnTest {

    @Test
    void countsOrdersByWarsawCalendarDay() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);

            // 2026-01-15 23:30 Warsaw (CET, UTC+1) is 22:30 UTC on the 15th.
            orders.place("c-1", Money.pln(100), Instant.parse("2026-01-15T22:30:00Z"));
            // 2026-01-15 23:30 UTC is 2026-01-16 00:30 Warsaw.
            orders.place("c-2", Money.pln(100), Instant.parse("2026-01-15T23:30:00Z"));
            orders.place("c-3", Money.pln(100), Instant.parse("2026-01-16T09:00:00Z"));

            assertEquals(1, orders.placedOn(LocalDate.of(2026, 1, 15)));
            assertEquals(2, orders.placedOn(LocalDate.of(2026, 1, 16)));
            assertEquals(0, orders.placedOn(LocalDate.of(2026, 1, 17)));
        }
    }
}
